# 3.5 — tệp .evtx bên trong: tiêu đề 4 KB + các chunk 64 KB, cờ DIRTY; log đầy nhanh cỡ nào (đo trên mẫu Security 31,5 MB của một máy chủ); bản ghi hỏng.
evtx-dau mau/*.evtx
@ps Get-ChildItem mau/*.evtx | ForEach-Object { [pscustomobject]@{ Tep = $_.Name.Substring(0,[math]::Min(34,$_.Name.Length)); Byte = $_.Length; 'Tru 4096, chia 65536' = ($_.Length - 4096) / 65536 } } | Format-Table -AutoSize
@ps $r = evtx-rec mau/security_big_sample.evtx | ConvertFrom-Json; $a = ($r.t | Measure-Object -Minimum -Maximum); $gio = ($a.Maximum - $a.Minimum).TotalHours; $mb = (Get-Item mau/security_big_sample.evtx).Length / 1MB; "{0:N0} su kien | {1:N1} MB | tu {2:yyyy-MM-dd HH:mm} den {3:yyyy-MM-dd HH:mm} UTC = {4:N1} gio" -f $r.Count, $mb, $a.Minimum, $a.Maximum, $gio; "{0:N0} su kien/gio | ~{1:N0} byte/su kien | 20 MB chua duoc ~{2:N1} gio" -f ($r.Count/$gio), ((Get-Item mau/security_big_sample.evtx).Length/$r.Count), ($gio*20/$mb)
@ps evtx-rec mau/security_big_sample.evtx | ConvertFrom-Json | Group-Object id | Sort-Object Count -Descending | Select-Object -First 8 Count,@{n='Id';e={$_.Name}},@{n='PhanTram';e={'{0:P0}' -f ($_.Count/62031)}} | Format-Table -AutoSize
evtx-rec mau/2-system-Security-dirty.evtx mau/sysmon.evtx 'mau/2-vss_0-Microsoft-Windows-TerminalServices-RemoteConnectionManager%4Operational.evtx' 2>&1 >/dev/null | cut -c1-160
@ps evtx-rec mau/2-system-Security-dirty.evtx | ConvertFrom-Json | Group-Object may | Select-Object Count,Name | Format-Table -AutoSize; evtx-rec mau/2-system-Security-dirty.evtx | ConvertFrom-Json | Where-Object id -in 1100,1102,1104,1105,4608,4616 | Sort-Object rec | Select-Object -First 9 @{n='UTC';e={$_.t.ToString('yyyy-MM-dd HH:mm:ss')}},id,may | Format-Table -AutoSize
